param([switch]$Console)
$ErrorActionPreference='Stop'
$framework=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319'
if(!(Test-Path -LiteralPath (Join-Path $framework 'csc.exe'))){$framework=Join-Path $env:WINDIR 'Microsoft.NET\Framework\v4.0.30319'}
$target=if($Console){'exe'}else{'winexe'}
$arguments=@('/nologo',('/target:'+$target),'/optimize+','/platform:x64','/main:Program',('/out:'+(Join-Path $PSScriptRoot 'AQServer.App.exe')),('/win32manifest:'+(Join-Path $PSScriptRoot 'app.manifest')),('/win32icon:'+(Join-Path $PSScriptRoot 'AQServer.ico')),('/resource:'+(Join-Path $PSScriptRoot 'AQServer.ico')+',AQServer.ico'),'/reference:System.dll','/reference:System.Management.dll','/reference:System.Web.Extensions.dll','/reference:System.Core.dll','/reference:System.Xml.dll','/reference:System.Drawing.dll','/reference:System.Windows.Forms.dll',('/reference:'+(Join-Path $framework 'System.Xaml.dll')),('/reference:'+(Join-Path $framework 'WPF\WindowsBase.dll')),('/reference:'+(Join-Path $framework 'WPF\PresentationCore.dll')),('/reference:'+(Join-Path $framework 'WPF\PresentationFramework.dll')),(Join-Path $PSScriptRoot 'Remote.cs'),(Join-Path $PSScriptRoot 'Main.cs'),(Join-Path $PSScriptRoot 'AssemblyInfo.cs'),(Join-Path $PSScriptRoot 'Tests.cs'),(Join-Path $PSScriptRoot 'Local.cs'),(Join-Path $PSScriptRoot 'Archive.cs'),(Join-Path $PSScriptRoot 'ArchiveUI.cs'),(Join-Path $PSScriptRoot 'ArchiveTests.cs'),(Join-Path $PSScriptRoot 'Capture.cs'),(Join-Path $PSScriptRoot 'CaptureTests.cs'),(Join-Path $PSScriptRoot 'LocalGpu.cs'),(Join-Path $PSScriptRoot 'Interaction.cs'),(Join-Path $PSScriptRoot 'InteractionTests.cs'),(Join-Path $PSScriptRoot 'Motion.cs'),(Join-Path $PSScriptRoot 'Charts.cs'),(Join-Path $PSScriptRoot 'MotionTests.cs'),(Join-Path $PSScriptRoot 'ThemeTests.cs'),(Join-Path $PSScriptRoot 'Compact.cs'),(Join-Path $PSScriptRoot 'CompactTests.cs'))
$sources=@('TrayTests.cs','TrayFlyout.cs','DesignReview.cs','About.cs','AppUpdates.cs','UpdatePublicKey.cs','UpdateTests.cs','PaneSizing.cs','V124Tests.cs','FooterLayoutTests.cs','V122Tests.cs','TerminalPreferences.cs','StartupTests.cs','V12Tests.cs','NumericMotion.cs','Shell.cs','Icons.cs','MiniCharts.cs','TransferDrawer.cs','FileNameCell.cs','TerminalInspector.cs','V11Tests.cs','Hardware.cs','ProcessActions.cs','Workspace.cs','ConPtySession.cs','TerminalWorkspace.cs','TerminalTests.cs','RemoteFiles.cs','Transfers.cs','FileBrowser.cs','HistoryProcessTests.cs','WorkbenchTests.cs','ArchiveLayout.cs','UiReview.cs','ConnectionProbe.cs')
foreach($source in $sources){$arguments+=(Join-Path $PSScriptRoot $source)}
foreach($dll in (Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'deps/sshnet') -Filter *.dll)){$arguments+=('/reference:'+$dll.FullName);Copy-Item -LiteralPath $dll.FullName -Destination $PSScriptRoot -Force}
foreach($name in @('Core','Wpf')){$dll=Join-Path $PSScriptRoot ('deps/webview2/sdk/lib/net462/Microsoft.Web.WebView2.'+$name+'.dll');$arguments+=('/reference:'+$dll);Copy-Item -LiteralPath $dll -Destination $PSScriptRoot -Force}
Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'deps/webview2/sdk/runtimes/win-x64/native/WebView2Loader.dll') -Destination $PSScriptRoot -Force
& (Join-Path $framework 'csc.exe') @arguments
if($LASTEXITCODE -ne 0){throw 'AQ Server build failed'}
Get-Item -LiteralPath (Join-Path $PSScriptRoot 'AQServer.App.exe') | Select-Object FullName,Length
